      { name: "DEWALT DWMT73810 Combination Wrench Set, 8-Piece Metric", price: "$33.72", rating: "4.8", reviews: "1,905", images: ["/images/dewalt-dwmt73810.svg"], asin: "B00PQXNG0M", specs: ["8 pieces", "Metric 10 to 19mm", "12-point box end", "Full polish chrome", "Long panel handle", "Cheapest useful set"], badge: "budget", label: "Best Budget", pros: "Ten to nineteen metric, full polish, and the DEWALT name for the price of a fast food lunch. No SAE sizes and no organizers, but the wrenches themselves are solid." },
      { name: "Sunex 9930M Metric Stubby Combination Wrench Set, 10-Piece", price: "$30.09", rating: "4.8", reviews: "1,161", images: ["/images/sunex-9930m-stubby.svg"], asin: "B000PGTCDU", specs: ["10 pieces", "Metric 10 to 19mm", "Stubby length", "12-point box end", "Full polish chrome", "For confined spaces"], badge: "best", label: "Best Stubby", pros: "The short-body set you buy for the one bolt the full-length wrench cannot swing on. Alternator, starter, and intake bolts where a normal wrench runs out of room." }
